def word_frequency(text: str) -> dict[str, int]:
    import string
    freq = {}
    for word in text.split():
        cleaned_word = word.strip(string.punctuation).lower()
        if cleaned_word:
            freq[cleaned_word] = freq.get(cleaned_word, 0) + 1
    return freq
